CREATE TABLE IF NOT EXISTS `pro_vouchers` (`id` INT AUTO_INCREMENT PRIMARY KEY, `code` VARCHAR(16) NOT NULL UNIQUE, `plan` VARCHAR(16) NOT NULL DEFAULT 'monthly', `days` INT NOT NULL DEFAULT 30, `max_uses` INT NOT NULL DEFAULT 1, `used_count` INT NOT NULL DEFAULT 0, `expires_at` DATETIME NULL, `created_by` INT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_voucher_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `pro_redemptions` (`id` INT AUTO_INCREMENT PRIMARY KEY, `voucher_id` INT NOT NULL, `user_id` INT NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `uq_redemption` UNIQUE (`voucher_id`, `user_id`), CONSTRAINT `fk_redeem_voucher` FOREIGN KEY (`voucher_id`) REFERENCES `pro_vouchers` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_redeem_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
